@if(!$fresh)<div class="notice warning"><span class="notice-icon">!</span><div><strong>{{ $source ? 'Queue telemetry is stale or unavailable' : 'Waiting for queue telemetry' }}</strong><p>Ready-agent counts are unavailable until the gateway receives a complete QueueStatus snapshot. Last-known member states are historical and must not drive dialing.</p></div></div>@endif
<div class="kpi-grid wallboard-kpis">@foreach(['ready'=>'Ready memberships','busy'=>'Busy memberships','paused'=>'Paused memberships','wrapup'=>'Reported wrap-up','offline'=>'Offline / unknown'] as $key=>$label)<article class="kpi"><div><span>{{ $label }}</span><span class="metric-icon">{{ $key==='ready' ? '◉' : '♧' }}</span></div><strong>{{ $fresh ? $totals[$key] : '—' }}</strong><small>{{ $fresh ? 'PBX queue membership states' : 'Fresh PBX snapshot required' }}</small></article>@endforeach</div>
<section class="panel"><div class="panel-heading"><div><h2>Queue performance</h2><p>PBX counters since queue statistics were last reset · {{ $source?->observed_at ?? 'No snapshot received' }} UTC</p></div><span class="pill {{ $fresh ? 'good' : 'warn' }}">{{ $fresh ? 'Fresh' : 'Unavailable / stale' }}</span></div><div class="table-scroll"><table><thead><tr><th>Queue</th><th>Waiting</th><th>Completed</th><th>Abandoned</th><th>Service level</th></tr></thead><tbody>@forelse($queues as $queue)<tr><td>{{ $queue->queue }}</td><td>{{ $queue->waiting }}</td><td>{{ $queue->completed }}</td><td>{{ $queue->abandoned }}</td><td>{{ $queue->service_level===null ? 'Not reported' : $queue->service_level.'%' }}</td></tr>@empty<tr><td colspan="5" class="empty-inline">No queue data received. Empty telemetry is not proof that no agents exist.</td></tr>@endforelse</tbody></table></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Agent & queue membership</h2><p>A member may appear in several queues. Wrap-up is shown only when PBX last-call and member wrap-up values are reported; inherited queue wrap-up and application sessions may be unreported.</p></div></div><div class="agent-grid">@forelse($members as $member)<article class="agent-card"><div class="agent-top"><span class="agent-avatar">{{ mb_substr($member->name ?: $member->interface,0,1) }}</span><span class="pill {{ !$fresh ? 'warn' : ($member->display_state==='ready' ? 'good' : 'neutral') }}">{{ $fresh ? ucfirst($member->display_state) : 'Stale' }}</span></div><h3>{{ $member->name ?: $member->interface }}</h3><p>{{ $member->interface }}</p><div><span>Queue {{ $member->queue }}</span><b>{{ $member->calls_taken }} calls</b></div></article>@empty<div class="empty"><span>♧</span><h3>No member telemetry yet</h3><p>The gateway needs queue-read permissions. Agent account provisioning belongs to the Agents & Queues module.</p></div>@endforelse</div>{{ $members->links() }}</section>
